}
B车间的工作过程可描述为：
while(1){
    生产一个产品B;
    P(empty2);    //判断货架F2是否有空
    P(mutex2);    //互斥访问货架F2
    将产品B存放到货架F2上;
    V(mutex2);    //释放货架F2
    V(full2);     //货架F2上的零件B的个数加1
}
装配车间的工作过程可描述为：
while(1){
    P(full1);     //判断货架F1上是否有产品A
    P(mutex1);    //互斥访问货架F1
    从货架F1上取一个A产品;
    V(mutex1);    //释放货架F1
    V(empty1);    //货架F1上的空闲空间数加1
    P(full2);     //判断货架F2上是否有产品B
    P(mutex2);    //互斥访问货架F2
    从货架F2上取一个B产品;
    V(mutex2);    //释放货架F2
    V(empty2);    //货架F2上的空闲空间数加1
    将取得的A产品和B产品组装成产品;
}

